  if(workflow==='PAPER')for(const t of state?.paper?.trades||[]){const lifecycle=t.lifecycle_id||t.id;if(!lifecycle||t.mode!=='PAPER'||!['LONG','SHORT'].includes(t.side))continue;add({id:lifecycle+':entry',lifecycle_id:lifecycle,kind:'ENTRY',entry_reason:t.entry_reason,signal_direction:t.signal_direction,side:t.side,contracts:t.contracts,price:t.entry_price,time:t.entry_time,workflow,symbol:t.symbol});const fills=t.exit_fills||[];for(const [i,f]of fills.entries())add({id:lifecycle+':exit:'+i,lifecycle_id:lifecycle,kind:'EXIT',exit_reason:f.reason,reason_verified:f.reason_verified,signal_direction:f.signal_direction,side:t.side,contracts:f.contracts,price:f.price,time:f.time,workflow,symbol:t.symbol});if(!fills.length&&t.status==='CLOSED')add({id:lifecycle+':exit',lifecycle_id:lifecycle,kind:'EXIT',side:t.side,contracts:t.contracts,price:t.exit_price,time:t.exit_time,workflow,symbol:t.symbol});}
