  document.querySelector('.work').insertAdjacentHTML('beforeend',`<section id="delta-india" class="view ${initialView==='delta-india'?'active':''}"><header class="head"><div><span class="label">CRYPTO DERIVATIVES</span><h1>Delta Exchange India</h1><small>Separate broker workspace · Public data · paper simulation · explicit live execution</small><a class="button secondary" href="#delta-ticket-panel">Order & runner</a> <a class="button secondary" href="#delta-connection-panel">Connection settings</a></div><div class="status" id="delta-mode">Read-only</div></header><section class="panel"><div class="step-title"><h2>Market & strategy</h2><span class="badge">INDIA</span></div><div class="field-grid delta-fields"><label class="field">Broker<select id="delta-broker"><option value="DELTA_INDIA">Delta Exchange India</option></select></label><label class="field">Workflow<select id="delta-workflow"><option value="READ_ONLY">Read-only analysis</option><option value="PAPER">Paper simulation</option><option value="LIVE">LIVE trading</option></select></label><label class="field">Contract type<select id="delta-type"><option value="">All supported derivatives</option></select></label><label class="field">Instrument search<input id="delta-search" placeholder="BTC, ETH, SOL, option strike…"></label><label class="field">Exact listed instrument<select id="delta-symbol"></select></label><label class="field">Timeframe<select id="delta-timeframe"><option value="5m">5 minutes</option><option value="15m">15 minutes</option><option value="30m">30 minutes</option><option value="1h">1 hour</option><option value="6h">6 hours</option><option value="1d">1 day</option></select></label><label class="field">RSI length<input id="delta-rsi" type="number" min="1" max="100" value="14"></label><label class="field">RSI MA<select id="delta-ma"><option>SMA</option><option>EMA</option></select></label><label class="field">RSI MA length<input id="delta-ma-length" type="number" min="1" max="100" value="14"></label></div><div class="packet-actions"><button id="delta-refresh" class="button">Refresh market</button><button id="delta-account" class="button secondary">Refresh account</button></div><p id="delta-auth" class="muted">Checking connection status…</p><p id="delta-catalog" class="muted">Listed India instruments load when this workspace opens.</p><p id="delta-note" class="muted">Delta routes independently. Forex pair routing is unavailable. Selecting LIVE and clicking Submit or Start authorizes that action.</p><div id="delta-message" class="handoff-status" role="status"></div><div class="risk-strip"><div><b id="delta-bid">—</b><small>Executable bid</small></div><div><b id="delta-ask">—</b><small>Executable ask</small></div><div><b id="delta-signal">—</b><small>Latest completed RSI cross</small></div></div><p id="delta-product" class="muted"></p></section><section class="panel" id="delta-current-position-panel" style="margin-top:16px"><details id="delta-workflow-disclosure" class="delta-disclosure" open><summary><strong>Selected workflow · Current open positions &amp; P&amp;L</strong><span id="delta-workflow-summary" class="muted" role="status">Loading workflow position…</span></summary><div id="delta-workflow-positions" tabindex="0" aria-label="Selected workflow current position table" style="overflow:auto"></div><div id="delta-workflow-pnl" role="status">Loading workflow position…</div><small>Native quote/settlement units · Paper and Live are separate · calculated Paper P&amp;L excludes fees/funding.</small></details></section><section class="panel" id="delta-ticket-panel" style="margin-top:16px"><div class="step-title"><h2>Order & runner</h2><span id="delta-ticket-mode" class="badge">READ-ONLY</span></div><div class="field-grid delta-fields"><label class="field">Side<select id="delta-side"><option value="buy">Bullish · buy ATM call</option><option value="sell">Bearish · buy ATM put</option></select></label><label class="field">Quantity · contracts<input id="delta-contracts" type="number" min="1" max="100000" step="1" value="1"><small>Whole Delta contracts; units shown above.</small></label><label class="field">Order type<select id="delta-order-type"><option value="limit_order">Limit order · price protected</option><option value="market_order">Market order · best available price</option></select></label><label class="field" id="delta-price-field">Option limit premium<input id="delta-price" type="number" min="0" step="any" placeholder="Exact tick-aligned price"></label><label class="field">Time in force<select id="delta-tif"><option value="ioc">IOC · cancel unfilled quantity</option><option value="gtc">GTC · remain open until cancelled</option></select></label><label class="field">Position control<select id="delta-reduce"><option value="false">Open / increase position</option><option value="true">Reduce only</option></select></label><label class="field">Strategy execution<select id="delta-strategy-mode"><option value="ATM_OPTIONS">Buy ATM call / buy ATM put</option></select><small>BTCUSD RSI signals · option premium positions only</small></label><label class="field">Signal direction<select id="delta-direction"><option value="BOTH">Bullish call and bearish put</option><option value="LONG_ONLY">Bullish call only</option></select></label><label class="field delta-trailing-choice"><span><input id="delta-trailing-enabled" type="checkbox"> Runner trailing stop · optional</span><small>Off by default · application-managed</small></label><label class="field">Trailing step mode<select id="delta-trailing-mode" disabled><option value="PERCENTAGE">Percentage of original filled entry</option><option value="POINTS">Quoted price points</option></select></label><label class="field">Trailing step<input id="delta-trailing-step" type="number" min="0.01" step="any" value="10" disabled></label></div><p id="delta-order-note" class="muted">Submit entry requires a fresh completed RSI crossover: buy bullish / sell bearish, then monitors only that filled position for the opposite crossover exit. No waiting entry, reentry or reversal. Submit has no trailing; trailing controls apply to Start Runner. Limit uses your specified price. Reduce-only skips entry signals and checks the existing position.</p><p id="delta-trailing-preview" class="muted">Runner trailing off.</p><p class="muted">Requested option runner: bullish underlying RSI buys ATM CALL; bearish buys ATM PUT. Held option exits on the opposite underlying crossover first, with no same-bar reversal. Both are long-premium entries; no futures shorts or option writing. Nearest unexpired expiry; closest strike to fresh underlying spot. Entries/exits use actual option bid/ask IOC limits. See current running configuration below.</p><div class="packet-actions"><button id="delta-submit" class="button">Submit Order</button><button id="delta-start" class="button">Start Runner</button><button id="delta-stop" class="button secondary">Stop strategy monitoring</button><button id="delta-close-runner" class="button secondary">Close owned strategy position</button><button id="delta-close" class="button secondary">Close paper position</button></div><p id="delta-ticket-auth" class="muted">Checking connection…</p><p id="delta-submit-condition" class="muted" role="status"></p><p id="delta-control-state" class="muted" role="status"></p><p id="delta-strategy-route-state" class="muted" role="status"></p><p id="delta-runner" class="muted">Runner stopped.</p><p id="delta-trailing-state" class="muted"></p><p class="muted">LIVE actions send real orders directly. Read-only mode cannot submit. Paper uses local simulations. Native broker funds and settlement assets are displayed without an invented INR conversion or margin estimate.</p><div id="delta-orders" style="overflow:auto"></div></section><section class="panel" style="margin-top:16px"><h2>Delta market chart</h2><p class="muted">Listed-contract candles · Wilder RSI and selected RSI MA · manual orders and explicitly started runner</p><div class="packet-actions"><button id="delta-chart-buy" class="button" disabled>Buy Call</button><button id="delta-chart-sell" class="button secondary" disabled>Buy Put</button></div><p id="delta-chart-route" class="muted">One-click strategy check: fresh completed bullish RSI cross buys a call; bearish buys a put. No qualifying signal means no order. Nearest unexpired expiry · ATM strike.</p><p id="delta-stream-health" class="muted">REST history · WebSocket not connected</p><div id="delta-chart"></div><div id="delta-events"></div><details id="delta-execution-disclosure" class="delta-disclosure" open><summary><strong>Actual option execution chart</strong><span id="delta-execution-summary" class="muted">Actual option premium candles and confirmed fill markers</span></summary><div id="delta-execution-chart">No recorded option execution for this workflow.</div></details></section><section class="panel" id="delta-account-panel" style="margin-top:16px"><details id="delta-account-disclosure" class="delta-disclosure" open><summary><strong>Live account · positions &amp; fills</strong><span id="delta-account-summary" class="muted">Loading authenticated account…</span></summary><p id="delta-account-status" class="muted">Loading authenticated account…</p><details id="delta-positions-disclosure" class="delta-disclosure" open><summary><strong>Current open positions · unrealized P&amp;L</strong><span id="delta-positions-summary" class="muted">Live broker positions</span></summary><div id="delta-live-positions" style="overflow:auto"></div></details><details id="delta-lifecycle-disclosure" class="delta-disclosure"><summary><strong>Position lifecycle history · last 30 days</strong><span id="delta-lifecycle-summary" class="muted">Live broker history</span></summary><div id="delta-live-fills" style="overflow:auto"></div><p id="delta-account-basis" class="muted"></p></details></details></section><section class="panel" id="delta-connection-panel" style="margin-top:16px"><details><summary>Connection settings · India API key</summary><div class="field-grid delta-fields"><label class="field">API key<input id="delta-key" type="password" autocomplete="off" placeholder="Existing India API key"></label><label class="field">API secret<input id="delta-secret" type="password" autocomplete="off" placeholder="Existing secret"></label></div><div class="packet-actions"><button id="delta-connect" class="button">Connect India account</button></div><p class="muted">Saved on this computer in a private file with owner-only permissions. Never stored in browser storage. Use your existing key from delta.exchange/app/account/manageapikeys with Trading permission and this computer’s IP whitelist. An environment-configured key takes precedence.</p></details><p id="delta-saved-credentials" class="muted">Saved credentials are held privately on this computer. Leave fields blank to keep them.</p><pre id="delta-account-text" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre></section><section class="panel" id="delta-paper-history-panel" style="margin-top:16px"><details id="delta-paper-disclosure" class="delta-disclosure"><summary><strong>Delta paper position history</strong><span id="delta-paper-summary" class="muted">Paper ledger only</span></summary><div id="delta-history" tabindex="0" aria-label="Paper position history table" style="overflow:auto"></div></details></section></section>`);
